        return res;
    }

    // 统计不包含数字 x 和 y 的子数组数（子数组中只能出现剩下的那个数）
    public static long countNoPair(int[] arr, int x, int y) {
        long res = 0;
        long cnt = 0;
        for (int v : arr) {
            if (v == x || v == y) {
                res += cnt * (cnt + 1) / 2;
                cnt = 0;
            } else {
                cnt++;
